/**
 * Call this function once to initialize the custom sprites, probably in your main.ts file
 */
export const initCustomSprites = (): void => {
    const images: ImageData[] = [
        { width: 29, height: 26, data: pngToBase64.groundEffectTab },
        { width: 29, height: 26, data: pngToBase64.launchSiteTab },   
        { width: 29, height: 26, data: pngToBase64.loadTab },
        { width: 29, height: 26, data: pngToBase64.sequenceTab },
        { width: 29, height: 26, data: pngToBase64.shellTab },
        { width: 29, height: 26, data: pngToBase64.showTab },
        { width: 23, height: 23, data: pngToBase64.arrowLeft },
        { width: 23, height: 23, data: pngToBase64.arrowRight },
        { width: 250, height: 250, data: pngToBase64.banner1 },
        { width: 250, height: 250, data: pngToBase64.banner2 },
        { width: 14, height: 250, data: pngToBase64.banner3 },
        { width: 16, height: 16, data: pngToBase64.ascendLoadsPresent },
        { width: 16, height: 16, data: pngToBase64.effectSphere },
        { width: 16, height: 16, data: pngToBase64.effectStar},
        { width: 16, height: 16, data: pngToBase64.effectRing },
        { width: 16, height: 16, data: pngToBase64.effectPalm },
        { width: 16, height: 16, data: pngToBase64.effectSprayBurst },
        { width: 16, height: 16, data: pngToBase64.effectShellOfShells},
        { width: 16, height: 16, data: pngToBase64.effectMicroBurst},
        { width: 16, height: 16, data: pngToBase64.effectCrackle},
        { width: 16, height: 16, data: pngToBase64.effectFlyingFish},
        { width: 16, height: 16, data: pngToBase64.effectSprayMine},
        { width: 16, height: 16, data: pngToBase64.effectSprayFan},
        { width: 16, height: 16, data: pngToBase64.effectCometMine},
        { width: 16, height: 16, data: pngToBase64.effectCometFan},
        { width: 16, height: 16, data: pngToBase64.effectFountain},
        { width: 16, height: 16, data: pngToBase64.effectWisp},
    ];
    // allocate memory slots for each image
    const range = ui.imageManager.allocate(images.length);

    // populate the memory slots with the images
    if (range) {
        images.forEach((image, index) => {
            ui.imageManager.setPixelData(range.start + index, {
                type: "png",
                palette: "closest",
                data: image.data,
            });
            imageMap[index] = range.start + index;
        });
    }
};
/**
 * Put this function in for the value for the image in a widget, e.g.:
 *
 *{..., width: 19, height: 20, image: customImageFor("sBendLeft"), ... }
 */
 export const customImageFor = (image: ImageStringNames): number => {
    return imageMap[ImageMoniker[image]];
};



export function sprite(id: number, colour?: Colour): string
{
    if (colour)
    {
        id |= (colour << 19) | (1 << 29);
    }

    return "{INLINE_SPRITE}{" + (id & 0xFF) + "}{" + ((id >> 8) & 0xFF) + "}{" + ((id >> 16) & 0xFF) + "}{" + ((id >> 24) & 0xFF) + "}";
}

let _colouredEffectSprites: number[][] = [];
let _effectDict: { [key: string]: number } = {"effectSphere": 0, "effectStar": 1, "effectRing": 2, "effectPalm": 3, "effectSprayBurst": 4, "effectShellOfShells": 5, 
    "effectMicroBurst": 6, "effectCrackle": 7, "effectFlyingFish": 8, "effectSprayMine": 9, "effectSprayFan": 10, "effectCometMine": 11, "effectCometFan": 12, "effectFountain": 13, "effectWisp": 14};
export function GetColouredEffectSprite(name: ImageStringNames, colour: Colour): number
{
    const spriteId = _colouredEffectSprites[_effectDict[name]]?.[colour];
    if (spriteId !== undefined) {
        return spriteId;
    }
    let val = colourSprite(customImageFor(name), colour);
    _colouredEffectSprites[_effectDict[name]] = _colouredEffectSprites[_effectDict[name]] || [];
    _colouredEffectSprites[_effectDict[name]][colour] = val;
    return val;
}


export function colourSprite(spriteId: number, colour: Colour): number {
    let id = ui.imageManager.allocate(1);
    if (id != undefined) {
        ui.imageManager.draw(id.start.valueOf(), {width:16, height:16}, ctx =>
        {   
            ctx.colour = colour;
            ctx.image(spriteId, 0, 0);
        });
        return id.start.valueOf();
    }
    return 0;
}